    if len(s) == 1:
        raise ValueError("'P' alone is not valid")

    # Check for week format: "P" followed by week count and "W", nothing else
    week_pattern = r'^P(\d+(?:\.\d+)?)W$'
    match = re.match(week_pattern, s)
    if match:
        weeks = float(match.group(1))
        return weeks * 7 * 86400

    # Now handle day/time format
    rest = s[1:]

    # Check for lowercase letters
    for ch in rest:
        if 'a' <= ch <= 'z':
            raise ValueError(f"Lowercase letter {ch!r} in: {s!r}")

    # Check that rest only contains valid characters: digits, '.', 'D', 'T', 'H', 'M', 'S'
    valid_chars = set('0123456789.DTHMS')
    for ch in rest:
        if ch not in valid_chars:
            raise ValueError(f"Invalid character {ch!r} in: {s!r}")

