    if not has_T:
        if rest.endswith('D'):
            day_str = rest[:-1]
            if day_str == '':
                raise ValueError(f"Day count missing in: {s!r}")
            if not re.match(r'^\d+(?:\.\d+)?$', day_str):
                raise ValueError(f"Invalid day count in: {s!r}")
            days = float(day_str)
            total_seconds += days * 86400
            has_any_count = True
        elif re.match(r'^\d+(?:\.\d+)?$', rest):
            raise ValueError(f"Day count without D in: {s!r}")
        else:
            raise ValueError(f"Invalid format in: {s!r}")

        if not has_any_count:
            raise ValueError(f"No count present in: {s!r}")

        return total_seconds

