            raise ValueError(f"Missing hour count in: {s!r}")
        if not re.match(r'^\d+(?:\.\d+)?$', h_before):
            raise ValueError(f"Invalid hour count in: {s!r}")
        hours = float(h_before)
        total_seconds += hours * 3600
        has_any_count = True
        time_part = time_part[h_pos+1:]
    else:
        time_part = time_part

    # Parse M
    if 'M' in time_part:
        m_pos = time_part.index('M')
        m_before = time_part[:m_pos]
        if m_before == '':
            raise ValueError(f"Missing minute count in: {s!r}")
        if not re.match(r'^\d+(?:\.\d+)?$', m_before):
            raise ValueError(f"Invalid minute count in: {s!r}")
        minutes = float(m_before)
        total_seconds += minutes * 60
        has_any_count = True
        time_part = time_part[m_pos+1:]
    else:
        pass

    # Parse S
    if 'S' in time_part:
        s_pos = time_part.index('S')
        s_before = time_part[:s_pos]
        if s_before == '':
            raise ValueError(f"Missing second count in: {s!r}")
        if not re.match(r'^\d+(?:\.\d+)?$', s_before):
            raise ValueError(f"Invalid second count in: {s!r}")
